package com.plugintoggler;

import net.runelite.client.config.Keybind;

/** One plugin and the key that toggles it. */
class Binding
{
	String plugin;
	int keyCode;
	int modifiers;
	/** A paused entry ignores its key. */
	boolean paused;
	/**
	 * False (the default): the on/off state is saved in RuneLite, so it is the same next session.
	 * True: the plugin is only started or stopped for this session and comes back as saved.
	 */
	boolean sessionOnly;

	Binding(String plugin)
	{
		this.plugin = plugin;
		this.keyCode = Keybind.NOT_SET.getKeyCode();
		this.modifiers = Keybind.NOT_SET.getModifiers();
	}

	Keybind keybind()
	{
		return new Keybind(keyCode, modifiers);
	}

	void setKeybind(Keybind k)
	{
		keyCode = k.getKeyCode();
		modifiers = k.getModifiers();
	}
}

package com.plugintoggler;

import java.util.ArrayList;
import java.util.List;

/** A named set of plugins with one key. The inherited "plugin" field holds the group's name. */
class Group extends Binding
{
	List<String> plugins = new ArrayList<>();

	Group(String name)
	{
		super(name);
	}
}

package com.plugintoggler;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JComponent;

/** A small flat icon button (arrow, cross, minus) that lights up when the mouse is over it. */
class IconButton extends JComponent
{
	enum Kind
	{
		UP, DOWN, CLOSE, MINUS
	}

	private static final Color IDLE = new Color(0x8f8f8f);
	private static final Color HOVER = Color.WHITE;
	private static final Color DANGER = new Color(0xff6b6b);

	private final Kind kind;
	private boolean hover;

	IconButton(Kind kind, String tip, Runnable action)
	{
		this.kind = kind;
		Dimension size = new Dimension(16, 16);
		setPreferredSize(size);
		setMinimumSize(size);
		setMaximumSize(size);
		setToolTipText(tip);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				repaint();
			}

			@Override
			public void mouseClicked(MouseEvent e)
			{
				action.run();
			}
		});
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		int cx = getWidth() / 2;
		int cy = getHeight() / 2;
		boolean danger = kind == Kind.CLOSE || kind == Kind.MINUS;
		g2.setColor(hover ? (danger ? DANGER : HOVER) : IDLE);
		g2.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		switch (kind)
		{
			case UP:
				g2.drawLine(cx - 3, cy + 1, cx, cy - 2);
				g2.drawLine(cx, cy - 2, cx + 3, cy + 1);
				break;
			case DOWN:
				g2.drawLine(cx - 3, cy - 1, cx, cy + 2);
				g2.drawLine(cx, cy + 2, cx + 3, cy - 1);
				break;
			case CLOSE:
				g2.drawLine(cx - 3, cy - 3, cx + 3, cy + 3);
				g2.drawLine(cx + 3, cy - 3, cx - 3, cy + 3);
				break;
			default:
				g2.drawLine(cx - 3, cy, cx + 3, cy);
				break;
		}
		g2.dispose();
	}
}

package com.plugintoggler;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import javax.swing.DefaultListModel;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.ListSelectionModel;
import javax.swing.event.AncestorEvent;
import javax.swing.event.AncestorListener;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;

/** A dialog with a search box and a list of plugin names to pick from. */
final class PluginPicker
{
	private PluginPicker()
	{
	}

	/** Returns the picked names, or an empty list if cancelled. With {@code multi} false at most one. */
	static List<String> pick(Component parent, String title, Collection<String> names, boolean multi)
	{
		List<String> all = new ArrayList<>(names);
		DefaultListModel<String> model = new DefaultListModel<>();
		JList<String> list = new JList<>(model);
		list.setSelectionMode(multi ? ListSelectionModel.MULTIPLE_INTERVAL_SELECTION
			: ListSelectionModel.SINGLE_SELECTION);
		JTextField field = new JTextField();
		Set<String> chosen = new LinkedHashSet<>();
		boolean[] updating = {false};

		Runnable refill = () ->
		{
			updating[0] = true;
			model.clear();
			String q = field.getText().trim().toLowerCase(Locale.ROOT);
			for (String n : all)
			{
				if (q.isEmpty() || n.toLowerCase(Locale.ROOT).contains(q))
				{
					model.addElement(n);
				}
			}
			List<Integer> keep = new ArrayList<>();
			for (int i = 0; i < model.size(); i++)
			{
				if (chosen.contains(model.get(i)))
				{
					keep.add(i);
				}
			}
			list.setSelectedIndices(keep.stream().mapToInt(Integer::intValue).toArray());
			updating[0] = false;
		};
		field.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				refill.run();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				refill.run();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				refill.run();
			}
		});
		// remember picks made while a filter hides the rest of the list
		list.addListSelectionListener(e ->
		{
			if (updating[0] || e.getValueIsAdjusting())
			{
				return;
			}
			for (int i = 0; i < model.size(); i++)
			{
				if (list.isSelectedIndex(i))
				{
					chosen.add(model.get(i));
				}
				else
				{
					chosen.remove(model.get(i));
				}
			}
		});
		// put the cursor in the search box as soon as the dialog opens
		field.addAncestorListener(new AncestorListener()
		{
			@Override
			public void ancestorAdded(AncestorEvent event)
			{
				field.requestFocusInWindow();
			}

			@Override
			public void ancestorRemoved(AncestorEvent event)
			{
			}

			@Override
			public void ancestorMoved(AncestorEvent event)
			{
			}
		});
		refill.run();

		JScrollPane scroll = new JScrollPane(list);
		scroll.setPreferredSize(new Dimension(260, 260));
		JPanel panel = new JPanel(new BorderLayout(0, 6));
		panel.add(field, BorderLayout.NORTH);
		panel.add(scroll, BorderLayout.CENTER);
		panel.add(new JLabel(multi ? "Search, then pick one or more (Ctrl-click)." : "Search, then pick one."),
			BorderLayout.SOUTH);

		int result = JOptionPane.showConfirmDialog(parent, panel, title, JOptionPane.OK_CANCEL_OPTION,
			JOptionPane.PLAIN_MESSAGE);
		if (result != JOptionPane.OK_OPTION)
		{
			return new ArrayList<>();
		}
		if (multi)
		{
			return new ArrayList<>(chosen);
		}
		String one = list.getSelectedValue();
		List<String> out = new ArrayList<>();
		if (one != null)
		{
			out.add(one);
		}
		return out;
	}
}

package com.plugintoggler;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("plugintoggler")
public interface PluginTogglerConfig extends Config
{
	@ConfigItem(
		keyName = "chatMessages",
		name = "Chat message",
		description = "Say in the game chat which plugin or group a hotkey turned on or off",
		position = 1
	)
	default boolean chatMessages()
	{
		return true;
	}

	@ConfigItem(
		keyName = "popup",
		name = "On-screen popup",
		description = "Show a small text on screen for a few seconds saying what a hotkey turned on or off. "
			+ "Hold Alt to drag it.",
		position = 2
	)
	default boolean popup()
	{
		return true;
	}

	@Range(min = 1, max = 10)
	@ConfigItem(
		keyName = "popupSeconds",
		name = "Popup seconds",
		description = "How long the on-screen popup stays up",
		position = 3
	)
	default int popupSeconds()
	{
		return 3;
	}
}

package com.plugintoggler;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.event.KeyEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;
import javax.inject.Inject;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.Keybind;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PluginChanged;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Lets you pick any installed plugin, or a group of plugins, and give it a hotkey that turns it
 * on and off. It only reacts to your key presses; it never plays the game for you.
 */
@PluginDescriptor(
	name = "RuneLite Plugin Toggler",
	description = "Turn any plugin, or a group of plugins, on and off with a hotkey, like Entity Hider",
	tags = {"hotkey", "keybind", "toggle", "plugin", "group", "entity hider"}
)
public class PluginTogglerPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(PluginTogglerPlugin.class);
	private static final String CONFIG_GROUP = "plugintoggler";
	private static final String BINDINGS_KEY = "bindings";
	private static final String GROUPS_KEY = "groups";

	/** The text form of everything, used by Export and Import. */
	static class Backup
	{
		List<Binding> bindings;
		List<Group> groups;
	}

	@Inject
	private Gson gson;

	@Inject
	private KeyManager keyManager;

	@Inject
	private PluginManager pluginManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private PluginTogglerConfig config;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private TogglePopupOverlay popupOverlay;

	@Provides
	PluginTogglerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PluginTogglerConfig.class);
	}

	private final List<Binding> bindings = new ArrayList<>();
	private final List<Group> groups = new ArrayList<>();
	private TogglePanel panel;
	private NavigationButton navButton;

	private final KeyListener keyListener = new KeyListener()
	{
		@Override
		public void keyTyped(KeyEvent e)
		{
		}

		@Override
		public void keyPressed(KeyEvent e)
		{
			Binding b = pressedEntry(e);
			if (b == null)
			{
				return;
			}
			e.consume();
			List<String> names = namesOf(b);
			String label = labelOf(b);
			boolean sessionOnly = b.sessionOnly;
			Component source = e.getComponent();
			SwingUtilities.invokeLater(() -> toggleNames(names, label, sessionOnly, source));
		}

		@Override
		public void keyReleased(KeyEvent e)
		{
		}
	};

	private static boolean matches(Binding b, KeyEvent e)
	{
		Keybind k = b.keybind();
		return !b.paused && !Keybind.NOT_SET.equals(k) && k.matches(e);
	}

	/** The entry whose key this is, if any. Single plugins win over groups. */
	private Binding pressedEntry(KeyEvent e)
	{
		for (Binding b : bindings)
		{
			if (matches(b, e))
			{
				return b;
			}
		}
		for (Group g : groups)
		{
			if (matches(g, e))
			{
				return g;
			}
		}
		return null;
	}

	private static List<String> namesOf(Binding b)
	{
		return b instanceof Group ? new ArrayList<>(((Group) b).plugins) : List.of(b.plugin);
	}

	/** The group's name, or null for a single plugin. */
	private static String labelOf(Binding b)
	{
		return b instanceof Group ? b.plugin : null;
	}

	@Override
	protected void startUp()
	{
		load();
		panel = new TogglePanel(this);
		panel.rebuild(bindings, groups);

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/icon.png");
		navButton = NavigationButton.builder()
			.tooltip("RuneLite Plugin Toggler")
			.icon(ImageUtil.resizeImage(icon, 16, 16))
			.priority(9)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(popupOverlay);
		keyManager.registerKeyListener(keyListener);
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(keyListener);
		overlayManager.remove(popupOverlay);
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
	}

	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.refreshStates();
			}
		});
	}

	/** Names of installed plugins that can be toggled, minus the ones in {@code exclude}. */
	private Set<String> availableNames(Collection<String> exclude)
	{
		Set<String> names = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
		for (Plugin p : pluginManager.getPlugins())
		{
			PluginDescriptor d = p.getClass().getAnnotation(PluginDescriptor.class);
			if (d == null || d.hidden() || p == this || exclude.contains(p.getName()))
			{
				continue;
			}
			names.add(p.getName());
		}
		return names;
	}

	private Plugin find(String name)
	{
		return pluginManager.getPlugins().stream()
			.filter(x -> x.getName().equals(name))
			.findFirst()
			.orElse(null);
	}

	// ---- editing the lists (all called from the panel, on the Swing thread) ----

	void promptAddBinding()
	{
		List<String> taken = new ArrayList<>();
		bindings.forEach(b -> taken.add(b.plugin));
		Set<String> names = availableNames(taken);
		if (names.isEmpty())
		{
			return;
		}
		List<String> picked = PluginPicker.pick(panel, "Add plugin hotkey", names, false);
		if (!picked.isEmpty())
		{
			bindings.add(new Binding(picked.get(0)));
			changed();
		}
	}

	void promptAddGroup()
	{
		String name = JOptionPane.showInputDialog(panel, "Name for the group:", "New plugin group",
			JOptionPane.PLAIN_MESSAGE);
		if (name == null || name.trim().isEmpty())
		{
			return;
		}
		Group g = new Group(name.trim());
		groups.add(g);
		changed();
		promptAddToGroup(g);
	}

	void promptAddToGroup(Group g)
	{
		Set<String> names = availableNames(g.plugins);
		if (names.isEmpty())
		{
			return;
		}
		List<String> picked = PluginPicker.pick(panel, "Add plugins to " + g.plugin, names, true);
		if (!picked.isEmpty())
		{
			g.plugins.addAll(picked);
			changed();
		}
	}

	void removeFromGroup(Group g, String member)
	{
		g.plugins.remove(member);
		changed();
	}

	void removeEntry(Binding b)
	{
		if (b instanceof Group)
		{
			groups.remove(b);
		}
		else
		{
			bindings.remove(b);
		}
		changed();
	}

	void moveEntry(Binding b, int delta)
	{
		List<? extends Binding> list = b instanceof Group ? groups : bindings;
		int from = list.indexOf(b);
		int to = from + delta;
		if (from < 0 || to < 0 || to >= list.size())
		{
			return;
		}
		Collections.swap(list, from, to);
		changed();
	}

	void setSessionOnly(Binding b, boolean sessionOnly)
	{
		b.sessionOnly = sessionOnly;
		saveAll();
	}

	/**
	 * The ON/OFF switch on a row. ON turns the plugin(s) on and lets the key work; OFF turns them
	 * off and makes the key do nothing.
	 */
	void setEntryOn(Binding b, boolean on)
	{
		b.paused = !on;
		saveAll();
		toggleNames(namesOf(b), labelOf(b), b.sessionOnly, on, null);
		changed();
	}

	/** 1 all on, 0 all off, 2 some on, -1 none of its plugins are installed. */
	int stateOf(Binding b)
	{
		int on = 0;
		int total = 0;
		for (String name : namesOf(b))
		{
			Plugin p = find(name);
			if (p == null)
			{
				continue;
			}
			total++;
			if (pluginManager.isPluginActive(p))
			{
				on++;
			}
		}
		return total == 0 ? -1 : on == 0 ? 0 : on == total ? 1 : 2;
	}

	// ---- export and import ----

	void exportDialog()
	{
		Backup backup = new Backup();
		backup.bindings = bindings;
		backup.groups = groups;
		JTextArea area = new JTextArea(gson.toJson(backup), 10, 28);
		area.setLineWrap(true);
		area.setEditable(false);
		area.selectAll();
		JPanel body = new JPanel(new BorderLayout(0, 6));
		body.add(new JLabel("Copy this text (Ctrl+C) and keep it somewhere safe."), BorderLayout.NORTH);
		body.add(new JScrollPane(area), BorderLayout.CENTER);
		JOptionPane.showMessageDialog(panel, body, "Export hotkeys", JOptionPane.PLAIN_MESSAGE);
	}

	void importDialog()
	{
		JTextArea area = new JTextArea(10, 28);
		area.setLineWrap(true);
		JPanel body = new JPanel(new BorderLayout(0, 6));
		body.add(new JLabel("<html>Paste exported text below.<br>This replaces your current hotkeys and groups.</html>"),
			BorderLayout.NORTH);
		body.add(new JScrollPane(area), BorderLayout.CENTER);
		int result = JOptionPane.showConfirmDialog(panel, body, "Import hotkeys", JOptionPane.OK_CANCEL_OPTION,
			JOptionPane.PLAIN_MESSAGE);
		if (result != JOptionPane.OK_OPTION)
		{
			return;
		}

		try
		{
			Backup backup = gson.fromJson(area.getText().trim(), Backup.class);
			if (backup == null)
			{
				throw new IllegalArgumentException("empty");
			}
			List<Binding> newBindings = new ArrayList<>();
			if (backup.bindings != null)
			{
				for (Binding b : backup.bindings)
				{
					if (b != null && b.plugin != null)
					{
						newBindings.add(b);
					}
				}
			}
			List<Group> newGroups = new ArrayList<>();
			if (backup.groups != null)
			{
				for (Group g : backup.groups)
				{
					if (g != null && g.plugin != null)
					{
						if (g.plugins == null)
						{
							g.plugins = new ArrayList<>();
						}
						newGroups.add(g);
					}
				}
			}
			bindings.clear();
			bindings.addAll(newBindings);
			groups.clear();
			groups.addAll(newGroups);
			changed();
		}
		catch (Exception e)
		{
			JOptionPane.showMessageDialog(panel, "That doesn't look like exported hotkeys.", "Import failed",
				JOptionPane.ERROR_MESSAGE);
		}
	}

	// ---- saving ----

	private void changed()
	{
		saveAll();
		if (panel != null)
		{
			panel.rebuild(bindings, groups);
		}
	}

	void saveAll()
	{
		configManager.setConfiguration(CONFIG_GROUP, BINDINGS_KEY, gson.toJson(bindings));
		configManager.setConfiguration(CONFIG_GROUP, GROUPS_KEY, gson.toJson(groups));
	}

	private void load()
	{
		bindings.clear();
		groups.clear();
		try
		{
			String json = configManager.getConfiguration(CONFIG_GROUP, BINDINGS_KEY);
			if (json != null && !json.isEmpty())
			{
				List<Binding> loaded = gson.fromJson(json, new TypeToken<List<Binding>>()
				{
				}.getType());
				if (loaded != null)
				{
					bindings.addAll(loaded);
				}
			}
			json = configManager.getConfiguration(CONFIG_GROUP, GROUPS_KEY);
			if (json != null && !json.isEmpty())
			{
				List<Group> loaded = gson.fromJson(json, new TypeToken<List<Group>>()
				{
				}.getType());
				if (loaded != null)
				{
					for (Group g : loaded)
					{
						if (g.plugins == null)
						{
							g.plugins = new ArrayList<>();
						}
					}
					groups.addAll(loaded);
				}
			}
		}
		catch (Exception e)
		{
			log.warn("Could not read saved hotkeys", e);
		}
	}

	// ---- toggling ----

	/**
	 * Flips the named plugins together: if any of them is on they all go off, otherwise they
	 * all go on. For a single plugin that is a plain on/off toggle. Unless {@code sessionOnly}, the
	 * result is saved in RuneLite so it is the same next session; with it, plugins are only stopped
	 * or started for now (so one switched off in the plugin list can't be turned on this way).
	 */
	private void toggleNames(List<String> names, String groupName, boolean sessionOnly, Component source)
	{
		toggleNames(names, groupName, sessionOnly, null, source);
	}

	/** As above, but with {@code forced} set the plugins are all put in that state instead of flipped. */
	private void toggleNames(List<String> names, String groupName, boolean sessionOnly, Boolean forced,
		Component source)
	{
		List<Plugin> targets = new ArrayList<>();
		List<String> missing = new ArrayList<>();
		List<String> failed = new ArrayList<>();
		List<String> blocked = new ArrayList<>();
		for (String name : names)
		{
			Plugin p = find(name);
			if (p == null)
			{
				log.warn("Plugin not found: {}", name);
				missing.add(name);
			}
			else
			{
				targets.add(p);
			}
		}
		if (targets.isEmpty())
		{
			say(groupName == null ? "couldn't find " + String.join(", ", missing)
				: groupName + " group has no plugins to toggle.", null, false);
			return;
		}

		boolean enable = forced != null ? forced : targets.stream().noneMatch(pluginManager::isPluginActive);
		List<String> changed = new ArrayList<>();
		for (Plugin target : targets)
		{
			if (pluginManager.isPluginActive(target) == enable)
			{
				continue;
			}
			if (sessionOnly && enable && !pluginManager.isPluginEnabled(target))
			{
				// RuneLite won't start a plugin that is switched off in its plugin list
				blocked.add(target.getName());
				continue;
			}
			if (setEnabled(target, enable, sessionOnly))
			{
				changed.add(target.getName());
			}
			else
			{
				failed.add(target.getName());
			}
		}

		String state = enable ? "on" : "off";
		String forNow = sessionOnly ? " (this session only)" : "";
		StringBuilder msg = new StringBuilder();
		if (groupName == null)
		{
			if (!changed.isEmpty())
			{
				msg.append(changed.get(0)).append(" turned ").append(state).append(forNow).append(".");
			}
		}
		else
		{
			msg.append(groupName).append(" group turned ").append(state).append(forNow);
			msg.append(changed.isEmpty() ? "." : ": " + String.join(", ", changed) + ".");
		}
		if (!blocked.isEmpty())
		{
			msg.append(" ").append(String.join(", ", blocked))
				.append(" is switched off in the plugin list, so it can't be turned on for this session only.");
		}
		if (!failed.isEmpty())
		{
			msg.append(" Couldn't toggle ").append(String.join(", ", failed)).append(".");
		}
		if (!missing.isEmpty())
		{
			msg.append(" Couldn't find ").append(String.join(", ", missing)).append(".");
		}
		// short text for the on-screen popup: "Entity Hider ON" or "Raiding group OFF (3)"
		String popupText = null;
		if (!changed.isEmpty())
		{
			String word = enable ? "ON" : "OFF";
			popupText = groupName == null ? changed.get(0) + " " + word
				: groupName + " group " + word + " (" + changed.size() + ")";
		}
		say(msg.toString().trim(), popupText, enable);
		refocus(source);
	}

	private boolean setEnabled(Plugin target, boolean enable, boolean sessionOnly)
	{
		try
		{
			if (!sessionOnly)
			{
				pluginManager.setPluginEnabled(target, enable);
			}
			if (enable)
			{
				pluginManager.startPlugin(target);
			}
			else
			{
				pluginManager.stopPlugin(target);
			}
			return true;
		}
		catch (Exception e)
		{
			log.warn("Could not toggle {}", target.getName(), e);
			return false;
		}
	}

	/**
	 * Starting or stopping a plugin makes RuneLite's plugin list grab focus for its search box.
	 * Hand focus back to where the key press came from (the game).
	 */
	private static void refocus(Component source)
	{
		if (source != null)
		{
			source.requestFocusInWindow();
			SwingUtilities.invokeLater(source::requestFocusInWindow);
		}
	}

	/** Tells the player what happened: in the game chat and/or in the on-screen popup, per the settings. */
	private void say(String chatText, String popupText, boolean enabled)
	{
		if (popupText != null && config.popup())
		{
			popupOverlay.show(popupText, enabled);
		}
		if (chatText.isEmpty() || !config.chatMessages())
		{
			return;
		}
		clientThread.invokeLater(() -> chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage("Plugin Toggler: " + chatText)
			.build()));
	}
}

package com.plugintoggler;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import javax.swing.JComponent;

/** An ON/OFF switch: a pill with a knob that slides and the word for the current side. Green when on. */
class SwitchToggle extends JComponent
{
	private static final Color ON = new Color(0x3fbf6a);
	private static final Color OFF = new Color(0x5a5a5a);

	private boolean on;

	SwitchToggle(boolean on, Consumer<Boolean> onChange)
	{
		this.on = on;
		Dimension size = new Dimension(54, 22);
		setPreferredSize(size);
		setMinimumSize(size);
		setMaximumSize(size);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				SwitchToggle.this.on = !SwitchToggle.this.on;
				repaint();
				onChange.accept(SwitchToggle.this.on);
			}
		});
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		int w = getWidth();
		int h = getHeight();
		g2.setColor(on ? ON : OFF);
		g2.fillRoundRect(0, 0, w, h, h, h);

		// the knob sits at one end, the word in the space left over at the other
		int d = h - 6;
		g2.setColor(Color.WHITE);
		g2.fillOval(on ? w - d - 3 : 3, 3, d, d);

		g2.setFont(getFont().deriveFont(Font.BOLD, 10f));
		FontMetrics fm = g2.getFontMetrics();
		String word = on ? "ON" : "OFF";
		int areaX = on ? 0 : h - 2;
		int areaW = w - h + 2;
		g2.setColor(on ? Color.WHITE : new Color(0xcfcfcf));
		g2.drawString(word, areaX + (areaW - fm.stringWidth(word)) / 2,
			(h - fm.getHeight()) / 2 + fm.getAscent());
		g2.dispose();
	}
}

package com.plugintoggler;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTabbedPane;
import net.runelite.client.config.Keybind;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/** Side panel with two tabs: single plugins, and groups of plugins. Each gets a key. */
class TogglePanel extends PluginPanel
{
	private static final Color ON = new Color(0x5fe08a);
	private static final Color OFF = new Color(0xff6b6b);
	private static final Color MIXED = new Color(0xf5c542);
	private static final String REMEMBER = "Remember across sessions";
	private static final String SESSION_ONLY = "This session only";

	private final PluginTogglerPlugin plugin;
	private final JPanel pluginRows = column();
	private final JPanel groupRows = column();
	/** One refresher per visible row, run whenever a plugin starts or stops. */
	private final List<Runnable> stateUpdaters = new ArrayList<>();

	TogglePanel(PluginTogglerPlugin plugin)
	{
		super(false);
		this.plugin = plugin;
		setLayout(new BorderLayout(0, 6));
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		JTabbedPane tabs = new JTabbedPane();
		tabs.addTab("Plugins", tab("Plugin hotkeys", "Pick a plugin to toggle with a key",
			plugin::promptAddBinding, pluginRows));
		tabs.addTab("Groups", tab("Plugin groups", "Make a group of plugins with one key",
			plugin::promptAddGroup, groupRows));
		add(tabs, BorderLayout.CENTER);

		JButton export = new JButton("Export");
		export.setToolTipText("Copy your hotkeys and groups as text");
		export.setFocusable(false);
		export.addActionListener(e -> plugin.exportDialog());
		JButton importer = new JButton("Import");
		importer.setToolTipText("Paste exported text to replace your hotkeys and groups");
		importer.setFocusable(false);
		importer.addActionListener(e -> plugin.importDialog());
		JPanel bar = new JPanel(new GridLayout(1, 2, 6, 0));
		bar.setOpaque(false);
		bar.add(export);
		bar.add(importer);
		add(bar, BorderLayout.SOUTH);
	}

	private static JPanel column()
	{
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setOpaque(false);
		return p;
	}

	private static JPanel tab(String titleText, String addTip, Runnable onAdd, JPanel rows)
	{
		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);
		JLabel title = new JLabel(titleText);
		title.setForeground(Color.WHITE);
		JButton add = new JButton("+");
		add.setToolTipText(addTip);
		add.setFocusable(false);
		add.addActionListener(e -> onAdd.run());
		header.add(title, BorderLayout.WEST);
		header.add(add, BorderLayout.EAST);

		JPanel north = new JPanel(new BorderLayout());
		north.setOpaque(false);
		north.add(rows, BorderLayout.NORTH);
		JScrollPane scroll = new JScrollPane(north);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.getVerticalScrollBar().setUnitIncrement(16);

		JPanel tab = new JPanel(new BorderLayout(0, 8));
		tab.setBorder(BorderFactory.createEmptyBorder(8, 4, 4, 4));
		tab.setOpaque(false);
		tab.add(header, BorderLayout.NORTH);
		tab.add(scroll, BorderLayout.CENTER);
		return tab;
	}

	void rebuild(List<Binding> bindings, List<Group> groups)
	{
		stateUpdaters.clear();
		fill(pluginRows, bindings.size(), "Click + to add a plugin.");
		for (Binding b : bindings)
		{
			pluginRows.add(entryCard(b, null));
			pluginRows.add(Box.createRigidArea(new Dimension(0, 6)));
		}
		fill(groupRows, groups.size(), "Click + to make a group.");
		for (Group g : groups)
		{
			groupRows.add(entryCard(g, memberList(g)));
			groupRows.add(Box.createRigidArea(new Dimension(0, 6)));
		}
		for (JPanel p : new JPanel[]{pluginRows, groupRows})
		{
			p.revalidate();
			p.repaint();
		}
	}

	/** Re-reads which plugins are on, to recolor the dots. Called when any plugin starts or stops. */
	void refreshStates()
	{
		for (Runnable r : new ArrayList<>(stateUpdaters))
		{
			r.run();
		}
	}

	private static void fill(JPanel rows, int count, String emptyHint)
	{
		rows.removeAll();
		if (count == 0)
		{
			JLabel hint = new JLabel(emptyHint);
			hint.setForeground(Color.LIGHT_GRAY);
			rows.add(hint);
		}
	}

	/** One card: dot and name with move/delete buttons, the middle part, the key, and the options. */
	private JPanel entryCard(Binding b, JComponent middle)
	{
		JPanel card = new JPanel(new BorderLayout(6, 6));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));

		JLabel dot = new JLabel("●");
		Runnable update = () ->
		{
			int state = plugin.stateOf(b);
			dot.setForeground(state == 1 ? ON : state == 0 ? OFF : state == 2 ? MIXED : Color.GRAY);
			dot.setToolTipText(state == 1 ? "On" : state == 0 ? "Off" : state == 2 ? "Some are on" : "Not installed");
		};
		stateUpdaters.add(update);
		update.run();

		JLabel name = new JLabel(b.plugin);
		name.setForeground(b.paused ? Color.GRAY : Color.WHITE);
		name.setToolTipText(b.paused ? "Off: its key does nothing" : null);

		JPanel title = new JPanel(new BorderLayout(6, 0));
		title.setOpaque(false);
		title.add(dot, BorderLayout.WEST);
		title.add(name, BorderLayout.CENTER);

		JPanel tools = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
		tools.setOpaque(false);
		tools.add(new IconButton(IconButton.Kind.UP, "Move up", () -> plugin.moveEntry(b, -1)));
		tools.add(new IconButton(IconButton.Kind.DOWN, "Move down", () -> plugin.moveEntry(b, 1)));
		tools.add(new IconButton(IconButton.Kind.CLOSE, b instanceof Group ? "Delete group" : "Remove",
			() -> plugin.removeEntry(b)));

		JPanel top = new JPanel(new BorderLayout(4, 0));
		top.setOpaque(false);
		top.add(title, BorderLayout.CENTER);
		top.add(tools, BorderLayout.EAST);

		JPanel body = column();
		if (middle != null)
		{
			body.add(left(middle));
			body.add(Box.createRigidArea(new Dimension(0, 6)));
		}
		body.add(left(keyRow(b)));
		body.add(Box.createRigidArea(new Dimension(0, 4)));
		body.add(left(options(b)));

		card.add(top, BorderLayout.NORTH);
		card.add(body, BorderLayout.CENTER);
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	private static <T extends JComponent> T left(T c)
	{
		c.setAlignmentX(LEFT_ALIGNMENT);
		return c;
	}

	private JPanel memberList(Group g)
	{
		JPanel middle = new JPanel(new BorderLayout(0, 4));
		middle.setOpaque(false);

		JPanel list = column();
		if (g.plugins.isEmpty())
		{
			JLabel none = new JLabel("No plugins yet");
			none.setForeground(Color.LIGHT_GRAY);
			list.add(none);
		}
		for (String member : g.plugins)
		{
			JPanel line = new JPanel(new BorderLayout(4, 0));
			line.setOpaque(false);
			JLabel l = new JLabel(member);
			l.setForeground(Color.LIGHT_GRAY);
			line.add(l, BorderLayout.CENTER);
			line.add(new IconButton(IconButton.Kind.MINUS, "Take out of the group",
				() -> plugin.removeFromGroup(g, member)), BorderLayout.EAST);
			list.add(line);
		}

		JButton addPlugins = new JButton("+ Add plugins");
		addPlugins.setFocusable(false);
		addPlugins.addActionListener(e -> plugin.promptAddToGroup(g));
		JPanel addRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		addRow.setOpaque(false);
		addRow.add(addPlugins);

		middle.add(list, BorderLayout.NORTH);
		middle.add(addRow, BorderLayout.CENTER);
		return middle;
	}

	/** The click-then-press key button, with a button beside it to toggle with the mouse. */
	private JPanel keyRow(Binding b)
	{
		JButton key = new JButton(label(b.keybind()));
		key.setToolTipText("Click, then press a key. Esc clears it.");
		key.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				key.setText("Press a key...");
				key.requestFocusInWindow();
			}
		});
		key.addKeyListener(new KeyAdapter()
		{
			@Override
			public void keyPressed(KeyEvent e)
			{
				int code = e.getKeyCode();
				if (code == KeyEvent.VK_SHIFT || code == KeyEvent.VK_CONTROL
					|| code == KeyEvent.VK_ALT || code == KeyEvent.VK_META)
				{
					return;
				}
				b.setKeybind(code == KeyEvent.VK_ESCAPE ? Keybind.NOT_SET : new Keybind(e));
				key.setText(label(b.keybind()));
				plugin.saveAll();
				e.consume();
			}
		});

		// ON turns the plugin on and enables the key; OFF turns the plugin off and disables the key
		SwitchToggle power = new SwitchToggle(!b.paused, on -> plugin.setEntryOn(b, on));
		power.setToolTipText("<html>ON: turns it on, and its key works.<br>OFF: turns it off, and its key does nothing.</html>");

		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setOpaque(false);
		row.add(key, BorderLayout.CENTER);
		row.add(power, BorderLayout.EAST);
		return row;
	}

	/** Whether the on/off state is kept after a restart or only for this session. */
	private JPanel options(Binding b)
	{
		JComboBox<String> mode = new JComboBox<>(new String[]{REMEMBER, SESSION_ONLY});
		mode.setSelectedItem(b.sessionOnly ? SESSION_ONLY : REMEMBER);
		mode.setFocusable(false);
		mode.setToolTipText("<html>" + REMEMBER + ": keeps its on/off state after a restart.<br>"
			+ SESSION_ONLY + ": reverts after a restart.</html>");
		mode.addActionListener(e -> plugin.setSessionOnly(b, SESSION_ONLY.equals(mode.getSelectedItem())));

		JPanel row = new JPanel(new BorderLayout());
		row.setOpaque(false);
		row.add(mode, BorderLayout.CENTER);
		return row;
	}

	private static String label(Keybind k)
	{
		return Keybind.NOT_SET.equals(k) ? "Not set" : k.toString();
	}
}

package com.plugintoggler;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * A small text that appears for a few seconds saying what a hotkey turned on or off.
 * Hold Alt to drag it; while Alt is held a sample shows so there is something to grab.
 */
class TogglePopupOverlay extends OverlayPanel
{
	private static final Color ON = new Color(0x5fe08a);
	private static final Color OFF = new Color(0xff6b6b);

	private final Client client;
	private final PluginTogglerConfig config;

	private static final long FADE_IN_MS = 180;
	private static final long FADE_OUT_MS = 450;

	private volatile String text;
	private volatile boolean on;
	private volatile long shownAt;
	private volatile long hideAt;

	@Inject
	TogglePopupOverlay(Client client, PluginTogglerConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	void show(String message, boolean enabled)
	{
		long now = System.currentTimeMillis();
		// a popup that is already up just changes its text; it doesn't fade in all over again
		if (text == null || now >= hideAt)
		{
			shownAt = now;
		}
		text = message;
		on = enabled;
		hideAt = now + Math.max(config.popupSeconds() * 1000L, FADE_IN_MS + FADE_OUT_MS);
	}

	/** 0 to 1: eases in over the first moments and out over the last. */
	private float opacity(long now)
	{
		float in = Math.min(1f, (now - shownAt) / (float) FADE_IN_MS);
		float out = Math.min(1f, (hideAt - now) / (float) FADE_OUT_MS);
		float t = Math.max(0f, Math.min(in, out));
		return t * t * (3f - 2f * t);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.popup())
		{
			return null;
		}

		long now = System.currentTimeMillis();
		String shown = text;
		boolean live = shown != null && now < hideAt;
		boolean sample = !live && client.isKeyPressed(KeyCode.KC_ALT);
		if (!live && !sample)
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text(sample ? "Plugin Toggler (drag me)" : shown)
			.color(sample ? Color.WHITE : on ? ON : OFF)
			.build());

		Composite before = graphics.getComposite();
		graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, sample ? 1f : opacity(now)));
		try
		{
			return super.render(graphics);
		}
		finally
		{
			graphics.setComposite(before);
		}
	}
}

